from __future__ import annotations

from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel
from .choice_delta import ChoiceDelta, ChoiceDeltaDict
from .choice_logprobs import ChoiceLogprobs, ChoiceLogprobsDict
from .enums.finish_reason import FinishReasonOrStr


class Choice(SdkBaseModel):
    delta: ChoiceDelta
    """A chat completion delta generated by streamed model responses."""

    finish_reason: Optional[FinishReasonOrStr] = UNSET
    index: int
    logprobs: Optional[ChoiceLogprobs] = UNSET


class ChoiceDict(TypedDict):
    delta: ChoiceDeltaDict
    finish_reason: NotRequired[FinishReasonOrStr]
    index: int
    logprobs: NotRequired[ChoiceLogprobsDict]
